INSERT INTO VIDEOS (channel_id, title, description, url, duration_seconds, uploaded_at) VALUES 
('51', 'Learn To Code Like a GENIUS and Not Waste Time', 'To try everything Brilliant has to offer—free—for a full 30 days, visit https://brilliant.org/TheCodingSloth/ . The first 200 of you will get 20% off Brilliant’s annual premium subscription. Learning to code is pretty overwhelming so this video should break down the essential steps and resources you need to start coding as a beginner. No prior experience required. I won\'t lie this probably isn\'t everything, but it is enough to get you started with coding. This isn\'t to get you a job, it\'s just a quick guide so you can start making your fun projects. This video was sponsored by Brilliant // NEWSLETTER // Sloth Bytes: https://slothbytes.beehiiv.com/subscribe // PROJECT BASED LEARNING RESOURCES // https://github.com/codecrafters-io/build-your-own-x https://github.com/aquadzn/learn-x-by-doing-y // BUSINESS INQUIRIES // For business: thecodingsloth@smoothmedia.co For brand partnerships: https://tally.so/r/mZVvKa // SOCIALS // Twitter: https://twitter.com/TheCodingSloth1 TikTok: https:', 'https://www.youtube.com/watch?v=q-_ezD9Swz4', '581', '2026-05-13'),
('74', 'coding is easy, actually', 'Improve your career using my code “EASY” for 30% off on all TripleTen\'s programs! Sign up for a FREE TripleTen career consultation with the link: https://get.tripleten.com/easyactually Did you solve TwoSum in O(n^2)? This is how you can recover. website shown for roadmap+projects is: roadmap dot sh the new community tab: https://discord.gg/w5VwJZD8Ge', 'https://www.youtube.com/watch?v=qkFYqY3vr84', '588', '2025-12-30'),
('25', 'How to Learn to Code', 'How to Learn to Code', 'https://www.youtube.com/watch?v=NGlX-1jhYJE', '73', '2026-01-26'),
('47', 'Introduction to Programming and Computer Science - Full Course', 'In this course, you will learn basics of computer programming and computer science. The concepts you learn apply to any and all programming languages and will be a good base onto which you can build your skills. This video is meant for those who are interested in computer science and programming but have no idea where to start and have little to no background information on coding. ✏️Course created by Steven and Sean from NullPointer Exception. Check out their channel: https://www.youtube.com/channel/UCmWDlvMYYEbW42B8JyxFBcA ❤️ Support for this channel comes from our friends at Scrimba – the coding platform that\'s reinvented interactive learning: https://scrimba.com/freecodecamp ⭐️ Course Contents ⭐️ ⌨️ (00:05) Introduction ⌨️ (01:37) What is Programming? ⌨️ (06:19) How do we write Code? ⌨️ (11:44) How do we get Information from Computers? ⌨️ (14:46) What can Computers Do? ⌨️ (20:43) What are Variables? ⌨️ (25:02) How do we Manipulate Varia', 'https://www.youtube.com/watch?v=zOjov-2OZ0E', '7149', '2025-09-22'),
('76', 'Every programming tutorial', 'thx for the explanation', 'https://www.youtube.com/watch?v=MAlSjtxy5ak', '29', '2025-05-30'),
('48', 'How to Learn Coding FAST And Make Cool Stuff', 'THE APP: https://play.google.com/store/apps/details?id=com.habitshow.app Most people struggle with coding because they get stuck in tutorials. This video offers a project-based learning approach, so you can start development by building real projects. And more... SUBSCRIBE to see more and 🥐 :) Free Articles ▲: https://eraysona.substack.com/ 𝕏 - https://x.com/eraysonayt more value - https://eraysona.com start learning - 00:00 problem with tutorials - 00:30 step 1: start coding - 01:15 step 2: build something you can\'t - 02:02 step 3: leverage everyone, everything for coding - 02:40 step 4: upward spiral - 03:28 keep going - 04:10 #coding #programming #software #learning', 'https://www.youtube.com/watch?v=nCZbZyyuHRg', '259', '2026-01-27'),
('4', 'How To Learn Programming for BEGINNERS! (2022/2023)', 'This simple tutorial will teach you how you can learn computer programming and teach yourself code. Learning code is not that hard, and it\'s easier than it looks. Instead of taking coding classes, why not teach yourself? Using this method you will learn html, css, javascript, visual design & more. Many people have landed themselves jobs involving web development and web design just with using this site. So what are you waiting for? Get started now! Learn Computer Programming (For FREE): https://www.freecodecamp.org/ Wondering what mic I used for this video? Click here: https://amzn.to/2D8EULN CroatCode\'s other videos: How To Make Reaction Videos ➜ • How To Make A Reaction Video for FREE! (SI... How To Make your Voice Sound Better on Audacity ➜ • How To Make Your Voice SOUND BETTER in Aud... Want more videos? - Subscribe ➜ https://bit.ly/2PXf2W2 Tweet me ► / croatcode Was this tutorial on learning computer programming helpful? Leave a like and share this video with a friend ', 'https://www.youtube.com/watch?v=bJzb-RuUcMU', '286', '2025-08-06'),
('67', 'the FUN way to learn programming', 'With code CRIN, Warp Pro is available for just $3 for the first month http://go.warp.dev/crin • how fast can you learn to code? (EXPERIMENT) Frequently asked questions will be answered in the pinned comment. Discord: discord.gg/RmCM7yKguu Stream: https://kick.com/crin1 00:00 - 00:21 Intro 00:21 - 04:13 Main rules 04:13 - 04:52 Languages 04:52 - 07:59 Projects 07:59 - 09:10 Useful app 09:10 - 10:29 Job 10:29 - 12:06 - Tips Intro song: • Toxic Joy - Temptation (ft. NEIV) [Arcade ...', 'https://www.youtube.com/watch?v=kNareBFFWtQ', '727', '2026-03-08'),
('71', 'How I Learned to Code in 4 Months & Got a Job! (No CS Degree, No Bootcamp)', 'I went from being a college dropout with zero technical skills to landing a software developer job in 4 months. This video is about how I became a self-taught software developer and how I learned how to code without a computer science degree or coding bootcamp. Connect With Me: ⭐️ Main Site: https://www.timkim.me/ 🐦 Twitter: https://twitter.com/TimKimdotcom 📸 Instagram: https://www.instagram.com/timkimdotcom Courses To Help Supplement Learning: (COUPON CODE FOR 10% OFF ➡️ FRIENDS10) 📚 Learning How To Learn: https://bit.ly/TK_LHTL_ZTM 🛠️ Build JS Projects Step-by-Step: https://bit.ly/TK_JS_ZTM 🟣 React: https://bit.ly/TK_React_ZTM 🅱️ Node: https://bit.ly/TK_Node_ZTM 🧐 Coding Interview Prep (DSA): https://bit.ly/TK_DSA_ZTM Learn How To Code Playlist: https://www.youtube.com/playlist?list=PLt3w0xGh6M0hpR26CyGYwGMFcsuLl8i8w Mentioned Resources: ⭐️ Learning How To Learn: https://bit.ly/Coursera_LearningHowToLearn 🏕️ FreeCodeCamp: https://www.freecode', 'https://www.youtube.com/watch?v=WR1ydijTx5E', '591', '2025-07-25'),
('76', 'C Programming Tutorial for Beginners', 'This course will give you a full introduction into all of the core concepts in the C programming language. ❤️ Support for this channel comes from our friends at Scrimba – the coding platform that\'s reinvented interactive learning: https://scrimba.com/freecodecamp ⭐️ Course Contents ⭐️ ⌨️ (0:00:00) Introduction ⌨️ (0:01:22) Windows Setup ⌨️ (0:05:02) Mac Setup ⌨️ (0:09:04) Hello World ⌨️ (0:12:51) Drawing a Shape ⌨️ (0:20:56) Variables ⌨️ (0:32:25) Data Types ⌨️ (0:38:32) Printf ⌨️ (0:45:22) Working With Numbers ⌨️ (0:52:20) Comments ⌨️ (0:56:00) Constants ⌨️ (1:00:13) Getting User Input ⌨️ (1:12:08) Building a Basic Calculator ⌨️ (1:17:43) Building a Mad Libs Game ⌨️ (1:26:29) Arrays ⌨️ (1:36:44) Functions ⌨️ (1:45:37) Return Statement ⌨️ (1:53:21) If Statements ⌨️ (2:07:11) Building a Better Calculator ⌨️ (2:14:51) Switch Statements ⌨️ (2:21:27) Structs ⌨️ (2:29:43) While Loops ⌨️', 'https://www.youtube.com/watch?v=KJgsSFOSQv0', '13573', '2025-11-18'),
('6', 'html tutorial for beginners to learn html for beginners html tutorial for beginners', 'hello please support me 😊😊 #shortsvideo #codewithharry ‪@CodeWithHarry‬ ‪@code‬', 'https://www.youtube.com/watch?v=u5vWFfZ6Csc', '5', '2025-09-08'),
('23', 'Best Programming Languages #programming #coding #javascript', 'Best Programming Languages #programming #coding #javascript', 'https://www.youtube.com/watch?v=5-oiLKEWIEw', '16', '2026-01-06'),
